function DnsCard({
  title,
  rows,
  onCopy,
  copiedKey,
}: {
  title: string;
  rows: Array<{
    label: string;
    value?: string;
    values?: string[];
    copy?: boolean;
    suffix?: string;
  }>;
  onCopy: (text: string, key: string) => void;
  copiedKey: string | null;
}) {
  return (
    <div className="rounded-lg border border-(--line-subtle) bg-(--bg-surface-secondary) p-4">
      <div className="mb-2 text-xs font-medium text-(--fg-brand)">{title}</div>
      <div className="space-y-1.5">
        {rows.map((row, idx) => (
          <div key={idx} className="text-xs text-(--fg-secondary)">
            {row.label}:{" "}
            {row.values ? (
              <div className="mt-1 space-y-1 pl-2">
                {row.values.map((v, i) => (
                  <div key={i} className="flex items-center gap-1.5">
                    <span className="text-(--fg-primary)">{v}</span>
                    {row.copy && (
                      <button
                        type="button"
                        onClick={() => onCopy(v, `${row.label}-${i}`)}
                        className="text-(--fg-secondary) transition-colors hover:text-(--fg-brand)"
                      >
                        {copiedKey === `${row.label}-${i}` ? (
                          <CheckCircle2 className="h-3.5 w-3.5 text-[#1DF6B5]" />
                        ) : (
                          <Copy className="h-3.5 w-3.5" />
                        )}
                      </button>
                    )}
                  </div>
                ))}
              </div>
            ) : (
              <span className="inline-flex items-center gap-1.5">
                <span className="text-(--fg-primary)">{row.value}</span>
                {row.copy && row.value && (
                  <button
                    type="button"
                    onClick={() =>
                      onCopy(row.value!, `${row.label}-${row.value}`)
                    }
                    className="text-(--fg-secondary) transition-colors hover:text-(--fg-brand)"
                  >
                    {copiedKey === `${row.label}-${row.value}` ? (
                      <CheckCircle2 className="h-3.5 w-3.5 text-[#1DF6B5]" />
                    ) : (
                      <Copy className="h-3.5 w-3.5" />
                    )}
                  </button>
                )}
                {row.suffix && (
                  <span className="text-(--fg-secondary)">{row.suffix}</span>
                )}
              </span>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

function CopyRow({
  label,
  value,
  onCopy,
  copied,
}: {
  label: string;
  value: string;
  onCopy: () => void;
  copied: boolean;
}) {
  return (
    <div className="flex items-center gap-2">
      <span className="text-(--fg-secondary)">{label}:</span>
      <div className="flex items-center gap-1.5">
        <span className="text-(--fg-primary)">{value}</span>
        <button
          type="button"
          onClick={onCopy}
          className="text-(--fg-secondary) transition-colors hover:text-(--fg-brand)"
        >
          {copied ? (
            <CheckCircle2 className="h-3.5 w-3.5 text-[#1DF6B5]" />
          ) : (
            <Copy className="h-3.5 w-3.5" />
          )}
        </button>
      </div>
    </div>
  );
}
